{
  "name": "CANalyst-II USB转CAN总线分析仪",
  "name_en": "CANalyst-II USB-to-CAN Bus Analyzer",
  "manufacturer": "",
  "description": "一种通过USB连接计算机的CAN总线分析与通信适配器，可用于发送、接收和监测CAN报文。在实验室中常用于嵌入式控制器、车载电子和工业设备的CAN网络联调、协议验证与故障排查。",
  "description_en": "A USB-connected CAN bus analysis and communication adapter used to send, receive, and monitor CAN frames. In laboratories it is commonly used for CAN network integration, protocol validation, and troubleshooting of embedded controllers, automotive electronics, and industrial equipment.",
  "tag_hints": [
    "CAN bus communication",
    "USB-to-CAN adapter",
    "CAN frame analysis",
    "embedded systems testing",
    "automotive electronics",
    "industrial bus diagnostics"
  ],
  "actions": [
    {
      "action_name": "auto-send",
      "description": "发送一条CAN报文到总线",
      "description_en": "Send a CAN frame onto the bus"
    },
    {
      "action_name": "auto-poll_received_messages",
      "description": "轮询设备并将新接收的CAN报文取入接收队列",
      "description_en": "Poll the device and move newly received CAN frames into the receive queue"
    },
    {
      "action_name": "auto-flush_tx_buffer",
      "description": "清空设备的CAN发送缓冲区",
      "description_en": "Flush the device's CAN transmit buffer"
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭CAN接口并停止总线通信",
      "description_en": "Shut down the CAN interface and stop bus communication"
    }
  ]
}

